before.content:
    var upload = retryable.beginUpload(new ResumableUpload(SCOPE, "text/plain", "data", 4, hash), NOW);
    retryable.putChunk(upload.uploadId(), new UploadChunk(0, "data".getBytes(StandardCharsets.UTF_8)), NOW);
    assertThrows(ArtifactError.class, () -> retryable.complete(upload.uploadId(), NOW));
    assertEquals(0, retryable.usage().storedBytes());
    assertEquals("sha256:" + hash, retryable.complete(upload.uploadId(), NOW.plusSeconds(1)).artifactId().value());
}

after.content:
    var upload = retryable.beginUpload(new ResumableUpload(SCOPE, "text/plain", "data", 4, hash), NOW);
    retryable.putChunk(upload.uploadId(), new UploadChunk(0, "data".getBytes(StandardCharsets.UTF_8)), NOW);
    assertThrows(ArtifactError.class, () -> retryable.complete(upload.uploadId(), NOW));
    var uploadDirectory = directory.resolve("fault").resolve("uploads").resolve(upload.uploadId());
    assertTrue(Files.isRegularFile(uploadDirectory.resolve("assembled.tmp")));
    assertFalse(Files.exists(uploadDirectory.resolve("0.chunk")));
    assertEquals(0, retryable.usage().storedBytes());
    assertEquals("sha256:" + hash, retryable.complete(upload.uploadId(), NOW.plusSeconds(1)).artifactId().value());
}
